/**
 * WASM module loader — PLAN.md §8 init contract / §13 deployment matrix.
 *
 * Phase A: the loader is INTERNAL to WASMengine. It does not export anything
 * from `tnaj`. The signature matches the Phase B `initWasm()` wrapper shape
 * (§13.8) so Phase B integration is a one-line forwarder.
 */

/**
 * Source for the WASM bytes. Default (`inline`) requires the bundler to
 * provide a base64 blob at build time (the actual `wasm-pack` artifact is
 * not yet built — wasm-pack must be installed first).
 */
export type InitWasmOptions =
  | { source: 'inline' }
  | { source: 'url'; url: string }
  | { source: 'bytes'; bytes: Uint8Array }
  | { source: 'instance'; instance: WebAssembly.Instance };

export interface WasmEngineExports {
  /** Bootstrap inner-loop. Returns flat 6*a*a result block. */
  bootstrap_inner_wasm: (
    a: number,
    n: number,
    perSeqWeights: Float64Array,
    perSeqRowTotals: Float64Array,
    originalWeights: Float64Array,
    iter: number,
    seed: number,
    methodCode: number,
    level: number,
    consistencyLo: number,
    consistencyHi: number,
    threshold: number,
  ) => Float64Array;
  /** Full bootstrap_tna. Result layout: 7*a*a + a (inits) + 1 (threshold). */
  bootstrap_tna_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    nStates: number,
    typeCode: number,
    scalingCsv: string,
    iter: number,
    seed: number,
    methodCode: number,
    level: number,
    consistencyLo: number,
    consistencyHi: number,
    threshold: number,
  ) => Float64Array;
  /** Permutation test. Result layout: 6*a*a (no inits, no threshold). */
  permutation_test_wasm: (
    valuesX: Int32Array,
    rowStartsX: Uint32Array,
    valuesY: Int32Array,
    rowStartsY: Uint32Array,
    nStates: number,
    typeCode: number,
    scalingCsv: string,
    iter: number,
    seed: number,
    adjustName: string,
    level: number,
    paired: number,
  ) => Float64Array;
  /** Reliability comparison: 22 metrics on two weight matrices. */
  compare_weight_matrices_wasm: (a: Float64Array, b: Float64Array, nStates: number) => Float64Array;
  /** Markov order test. Result layout: 7*(max_order+1) + 3. */
  markov_order_test_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    maxOrder: number,
    nPerm: number,
    alpha: number,
    seed: number,
  ) => Float64Array;
  /** Centrality stability. Result layout: 3 + 12*nDropProps (3 measures, 4 stats). */
  estimate_cs_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    nStates: number,
    typeCode: number,
    scalingCsv: string,
    measuresCsv: string,
    iter: number,
    dropProps: Float64Array,
    threshold: number,
    certainty: number,
    seed: number,
    corrMethod: string,
    loops: number,
  ) => Float64Array;
  /** RNG probe — used by the ABI parity test only. */
  rng_next_n: (seed: number, n: number) => Uint32Array;
  /** Centralities (10 measures). Result: n_measures × n_states, measure-major. */
  centralities_wasm: (
    weights: Float64Array,
    nStates: number,
    measuresCsv: string,
    loops: number,
    normalize: number,
  ) => Float64Array;
  /** Passage time (MFPT + π + persistence). Result: n*n + 2*n. */
  passage_time_wasm: (p: Float64Array, nStates: number, normalize: number) => Float64Array;
  /** Markov stability. Result: 6*n + n*n + 2*n. */
  markov_stability_wasm: (p: Float64Array, nStates: number, normalize: number) => Float64Array;
  /** HON embedding (Jacobi SVD). Result: n*dim + dim + 2. */
  honem_wasm: (
    adj: Float64Array,
    nNodes: number,
    dimReq: number,
    maxPower: number,
  ) => Float64Array;
  /** Path-dependence — JSON string. */
  path_dependence_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    labelsCsv: string,
    order: number,
    minCount: number,
    base: number,
  ) => string;
  /** Multi-order generative model — JSON string. */
  mogen_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    maxOrder: number,
    criterion: string,
    lrtAlpha: number,
  ) => string;
  /** HYPA (hypergeometric path anomaly) — JSON string. */
  hypa_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    labelsCsv: string,
    k: number,
    alpha: number,
    minCount: number,
    pAdjust: string,
  ) => string;
  /** HON (Higher-Order Network) — JSON string. */
  hon_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    labelsCsv: string,
    maxOrder: number,
    minFreq: number,
    collapseRepeats: number,
    method: string,
  ) => string;
  /** pathways via HON — '\n'-joined string. */
  pathways_hon_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    labelsCsv: string,
    maxOrder: number,
    minFreq: number,
    collapseRepeats: number,
    method: string,
    minCount: number,
  ) => string;
  /** pathways via HYPA — '\n'-joined string. */
  pathways_hypa_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    labelsCsv: string,
    k: number,
    alpha: number,
    minCount: number,
    pAdjust: string,
    pathwaysType: string,
  ) => string;
  /** pathways via MOGEN — '\n'-joined string. */
  pathways_mogen_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    labelsCsv: string,
    maxOrder: number,
    criterion: string,
    lrtAlpha: number,
    pathwaysOrderNeg1ForOptimal: number,
    minCount: number,
  ) => string;
  /** casedropReliability — flat result block; see wasm_bindings.rs for layout. */
  casedrop_reliability_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    nStates: number,
    typeCode: number,
    scalingCsv: string,
    iter: number,
    dropProps: Float64Array,
    threshold: number,
    certainty: number,
    method: string,
    includeDiag: number,
    seed: number,
  ) => Float64Array;
  /** reliabilityAnalysis — flat result block; see wasm_bindings.rs for layout. */
  reliability_analysis_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    nStates: number,
    typeCode: number,
    scalingCsv: string,
    iter: number,
    split: number,
    seed: number,
  ) => Float64Array;
  /** clusterData/clusterSequences (string path) — flat result; see wasm_bindings.rs. */
  cluster_string_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    k: number,
    methodCode: number,
    dissCode: number,
    weighted: number,
    lambda: number,
  ) => Float64Array;
  /** computeDendrogram — hierarchical on a precomputed n×n distance matrix. */
  cluster_from_dist_wasm: (
    dist: Float64Array,
    n: number,
    k: number,
    methodCode: number,
  ) => Float64Array;
  /** clusterData (numeric path) — flat result; see wasm_bindings.rs. */
  cluster_numeric_wasm: (
    data: Float64Array,
    n: number,
    p: number,
    k: number,
    methodCode: number,
    metricCode: number,
  ) => Float64Array;
  /**
   * MMM (mixture Markov model) — basic deterministic EM clustering.
   * Result: 8 + n + n*k + k + k*s + k*s*s. `initPosterior` empty ⇒ seeded
   * xoshiro init. See wasm_bindings.rs `mmm_wasm` for the layout.
   */
  mmm_wasm: (
    values: Int32Array,
    rowStarts: Uint32Array,
    nStates: number,
    k: number,
    maxIter: number,
    tol: number,
    alpha: number,
    seed: number,
    nStarts: number,
    initPosterior: Float64Array,
  ) => Float64Array;
}

/**
 * Node-target loader (uses pkg/, --target=nodejs). Used by the test
 * runners (vitest) and any node-side benchmarks.
 *
 * For the browser path, use `ts/load-web.ts` instead — it imports pkg-web
 * statically so vite library builds can bundle only the web target.
 */
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { setExports, isInitialized } from './load-shared.js';
export { isInitialized, getExports } from './load-shared.js';

/**
 * Locate the wasm-pack node artifact independent of how this loader is
 * being run. The collapse made one file serve two contexts whose relative
 * depth to `<repo>/wasm/pkg` differs: source-via-tsx (`src/wasm-engine/`,
 * 2 levels) and bundled (`dist/` chunk, 1 level). A fixed relative literal
 * cannot satisfy both; walking up from `import.meta.url` to the first
 * `wasm/pkg/tnaj_wasm.js` is depth-independent and works for either.
 */
function resolveWasmPkg(): string {
  let dir = dirname(fileURLToPath(import.meta.url));
  for (let i = 0; i < 8; i++) {
    const cand = join(dir, 'wasm', 'pkg', 'tnaj_wasm.js');
    if (existsSync(cand)) return cand;
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return join(dirname(fileURLToPath(import.meta.url)), '..', 'wasm', 'pkg', 'tnaj_wasm.js');
}

export async function initWasmEngine(_opts: InitWasmOptions = { source: 'inline' }): Promise<void> {
  if (isInitialized()) return;
  try {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore — generated by wasm-pack, no .d.ts at lib-build time
    const mod = (await import(pathToFileURL(resolveWasmPkg()).href)) as unknown as WasmEngineExports;
    setExports({
      bootstrap_inner_wasm: mod.bootstrap_inner_wasm,
      bootstrap_tna_wasm: mod.bootstrap_tna_wasm,
      permutation_test_wasm: mod.permutation_test_wasm,
      compare_weight_matrices_wasm: mod.compare_weight_matrices_wasm,
      markov_order_test_wasm: mod.markov_order_test_wasm,
      estimate_cs_wasm: mod.estimate_cs_wasm,
      rng_next_n: mod.rng_next_n,
      centralities_wasm: mod.centralities_wasm,
      passage_time_wasm: mod.passage_time_wasm,
      markov_stability_wasm: mod.markov_stability_wasm,
      honem_wasm: mod.honem_wasm,
      path_dependence_wasm: mod.path_dependence_wasm,
      mogen_wasm: mod.mogen_wasm,
      hypa_wasm: mod.hypa_wasm,
      hon_wasm: mod.hon_wasm,
      pathways_hon_wasm: mod.pathways_hon_wasm,
      pathways_hypa_wasm: mod.pathways_hypa_wasm,
      pathways_mogen_wasm: mod.pathways_mogen_wasm,
      casedrop_reliability_wasm: mod.casedrop_reliability_wasm,
      reliability_analysis_wasm: mod.reliability_analysis_wasm,
      cluster_string_wasm: mod.cluster_string_wasm,
      cluster_from_dist_wasm: mod.cluster_from_dist_wasm,
      cluster_numeric_wasm: mod.cluster_numeric_wasm,
      mmm_wasm: mod.mmm_wasm,
    });
  } catch (e) {
    throw new Error(
      `initWasmEngine: failed to load wasm pkg — has wasm-pack been run? ` +
        `Underlying error: ${(e as Error).message}`,
    );
  }
}
