/**
 * tnaw initialization. Call once at app start before any heavy function.
 *
 *   import { initTnaw, bootstrapTna } from 'tnaj/wasm';
 *   await initTnaw();
 *   const r = bootstrapTna(model, opts);
 *
 * The init is idempotent. If WASM fails to load, every heavy-function call
 * will throw — there is no JS fallback in tnaw. Use plain `tnaj` if you
 * need a fallback path.
 */
import { initWasmEngine, isInitialized } from '../wasm-engine/index.js';

let _initPromise: Promise<void> | null = null;

export async function initTnaw(): Promise<void> {
  if (isInitialized()) return;
  if (_initPromise) return _initPromise;
  _initPromise = initWasmEngine();
  await _initPromise;
}

export function isTnawReady(): boolean {
  return isInitialized();
}

function assertReady(): void {
  if (!isInitialized()) {
    throw new Error(
      'tnaw: WASM engine not initialized. Call `await initTnaw()` before using any tnaw function.',
    );
  }
}

export { assertReady };
